<script>
const csrf=<?=json_encode($csrf)?>,el=id=>document.getElementById(id),count=el('count'),rows=el('rows'),statusEl=el('status'),feedback=el('feedback'),filter=el('filter'),refreshBtn=el('refreshBtn'),radiusFrame=el('radiusFrame');let sessions=[];filter.value='';const healthSummary=document.createElement('div');healthSummary.className='feedback show info';healthSummary.textContent='Verificando RADIUS, SNMP e SSH...';document.querySelector('.subtitle').after(healthSummary);
const fmt=n=>{n=Number(n||0);let u=['B','KB','MB','GB','TB'],i=0;while(n>=1024&&i<4){n/=1024;i++}return n.toFixed(i?2:0)+' '+u[i]},esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function openModal(id){el(id).classList.add('open');document.body.style.overflow='hidden'}function closeModal(id){el(id).classList.remove('open');if(id==='radiusModal')radiusFrame.src='about:blank';document.body.style.overflow=''}function notice(message,type='info'){feedback.textContent=message;feedback.className='feedback show '+type;clearTimeout(notice.timer);notice.timer=setTimeout(()=>feedback.className='feedback '+type,7000)}
function render(){let q=filter.value.toLowerCase(),list=sessions.filter(x=>[x.username,x.nome,x.framedipaddress,x.callingstationid].join(' ').toLowerCase().includes(q));rows.innerHTML=list.map(x=>`<tr><td><a class="login" href="detail.php?login=${encodeURIComponent(x.username)}">${esc(x.nome||x.username)}<br><small>${esc(x.username)}</small></a></td><td>${esc(x.framedipaddress)}</td><td>${esc(x.callingstationid)}</td><td>${esc(x.nasportid)}</td><td>${esc(x.acctupdatetime)}</td><td>${fmt(x.acctoutputoctets)}</td><td>${fmt(x.acctinputoctets)}</td><td><div class="row-actions"><a class="btn" href="detail.php?login=${encodeURIComponent(x.username)}">TRÁFEGO</a><button class="danger" onclick="disconnectClient('${esc(x.username)}')">DESCONECTAR</button></div></td></tr>`).join('')}
async function load(manual=false){refreshBtn.disabled=true;try{let r=await fetch('api_sessions.php?_='+Date.now(),{cache:'no-store'}),j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'Falha ao consultar sessões.');sessions=j.sessions||[];count.textContent=j.count??sessions.length;render();let t=new Date().toLocaleTimeString();statusEl.textContent='Última atualização: '+t;if(manual)notice(`${sessions.length} sessões atualizadas às ${t}.`,'ok')}catch(e){notice(e.message,'error')}finally{refreshBtn.disabled=false}}
async function disconnectClient(login){if(!confirm(`Desconectar ${login} do Huawei agora? O cliente perderá a conexão PPPoE.`))return;let fd=new FormData();fd.append('csrf',csrf);fd.append('login',login);try{let r=await fetch('api_disconnect.php',{method:'POST',body:fd}),j=await r.json();if(!r.ok||!j.ok)throw Error(j.error);notice(j.message,'ok');setTimeout(()=>load(),1500)}catch(e){notice('Não foi possível desconectar: '+e.message,'error')}}
async function testCard(id,url){let card=el(id),p=card.querySelector('p');card.className='test-card running';p.textContent='Testando…';try{let r=await fetch(url+'?_='+Date.now(),{method:url==='api_sessions.php'?'GET':'POST',cache:'no-store'}),j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'Falha no teste.');card.className='test-card ok';p.textContent=url==='api_sessions.php'?`${j.count??0} sessões Huawei encontradas no RADIUS.`:j.message;return true}catch(e){card.className='test-card error';p.textContent=e.message;return false}}
async function runTests(){el('runTests').disabled=true;let results=await Promise.all([testCard('testRadius','api_sessions.php'),testCard('testSnmp','api_health.php'),testCard('testSsh','api_coa_health.php')]);el('runTests').disabled=false;if(results.every(Boolean))notice('RADIUS, SNMP e CoA validados.','ok')}
async function loadConfig(first=false){let j=await fetch('api_config.php').then(r=>r.json()),c=j.config||{},f=el('configForm');f.snmp_host.value=c.snmp_host||'';f.ssh_host.value=c.ssh_host||'';f.ssh_port.value=c.ssh_port||22;f.ssh_user.value=c.ssh_user||'';f.snmp_community.placeholder=c.has_snmp_community?'Configurada — deixe vazio para manter':'Obrigatória';f.ssh_password.placeholder=c.has_ssh_password?'Configurada — deixe vazio para manter':'Obrigatória';if(first&&(!c.snmp_host||!c.ssh_host||!c.ssh_user||!c.has_snmp_community||!c.has_ssh_password))openModal('configModal')}
async function saveConfig(test=false){let fd=new FormData(el('configForm'));fd.append('csrf',csrf);let r=await fetch('api_config.php',{method:'POST',body:fd}),j=await r.json();if(!r.ok||!j.ok){notice(j.error||'Falha ao salvar.','error');return}notice(j.message,'ok');closeModal('configModal');if(test){openModal('connectModal');runTests()}}
function generateUser(){let bytes=new Uint8Array(12);crypto.getRandomValues(bytes);let pass='MkA@'+Array.from(bytes,b=>(b%36).toString(36)).join('')+'#26';el('userCommand').textContent=`system-view\nssh user mkauth-addon\naaa\n local-user mkauth-addon password irreversible-cipher ${pass}\n local-user mkauth-addon service-type ssh\n local-user mkauth-addon level 3\n quit\nssh user mkauth-addon authentication-type password\nssh user mkauth-addon service-type stelnet\ncommit\nreturn`;let f=el('configForm');f.ssh_user.value='mkauth-addon';f.ssh_password.value=pass}
async function wizard(action,confirmWord=''){let fd=new FormData();fd.append('csrf',csrf);fd.append('action',action);fd.append('alias',el('wizAlias').value);fd.append('community',el('wizCommunity').value);fd.append('confirm',confirmWord);el('wizReport').textContent='Executando '+action+'…';try{let r=await fetch('api_wizard.php',{method:'POST',body:fd}),j=await r.json();if(!r.ok||!j.ok&&action!=='apply')throw Error(j.error||'Falha no Wizard.');let report=`IP de origem MK-AUTH: ${j.source_ip||'-'}\nSNMP existente: ${j.snmp_configured?'sim':'não identificado'}\nACL identificada: ${j.acl_detected?'sim':'não identificado'}\nResultado: ${j.message||j.error||'-'}`;if(j.commands)report+='\n\nCOMANDOS UTILIZADOS:\n'+j.commands;if(j.test_output)report+='\n\nTESTE FINAL:\n'+j.test_output;el('wizReport').textContent=report;notice(j.message||'Wizard concluído.',j.ok?'ok':'error')}catch(e){el('wizReport').textContent='ERRO: '+e.message;notice(e.message,'error')}}
function cleanRadiusFrame(){if(!radiusFrame.src||radiusFrame.src==='about:blank')return;try{let d=radiusFrame.contentDocument,s=d.createElement('style');s.textContent=`html,body{margin:0!important;padding:0!important;background:#f4f7fb!important}body>*:not(main.radius-app){display:none!important}main.radius-app{display:block!important;margin:0!important;padding:16px!important;max-width:none!important}.radius-hero,.radius-summary,.radius-lines-form,.radius-nas-filter,.radius-actions,.radius-status-row{display:none!important}.radius-controls{margin:0 0 12px!important;padding:14px!important}.radius-control-row{display:block!important}.radius-toolbar{margin-top:12px!important;display:block!important}.radius-search{width:100%!important;max-width:none!important}.radius-log-panel{margin:0!important}.radius-log-list{max-height:none!important;height:auto!important}`;d.head.appendChild(s);let q=d.getElementById('radiusSearch');if(q)q.placeholder='Pesquisar eventos pelo login'}catch(e){notice('Modo compacto indisponível.','error')}}
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeModal(b.dataset.close));refreshBtn.onclick=()=>load(true);el('connectBtn').onclick=()=>{openModal('connectModal');runTests()};el('runTests').onclick=runTests;el('radiusBtn').onclick=()=>{radiusFrame.src='/admin/addons/radius/index.php?linhas=100';openModal('radiusModal')};el('configBtn').onclick=()=>{loadConfig();openModal('configModal')};el('userBtn').onclick=()=>{generateUser();openModal('userModal')};el('newPassword').onclick=generateUser;el('copyUser').onclick=async()=>{await navigator.clipboard.writeText(el('userCommand').textContent);notice('Comandos copiados.','ok')};el('wizardBtn').onclick=()=>openModal('wizardModal');el('wizInventory').onclick=()=>wizard('inventory');el('wizManual').onclick=()=>wizard('generate');el('wizAuto').onclick=()=>{let word=prompt('Esta ação alterará ACL e SNMP no Huawei. Digite APLICAR para confirmar:');if(word==='APLICAR')wizard('apply',word)};el('copyWizard').onclick=async()=>{await navigator.clipboard.writeText(el('wizReport').textContent);notice('Relatório copiado.','ok')};el('configForm').onsubmit=e=>{e.preventDefault();saveConfig(false)};el('configTest').onclick=()=>saveConfig(true);filter.oninput=render;loadConfig(true);load();
</script>
<script>
(function(){
 const grid=document.querySelector('#wizardModal .form-grid'),aliasField=el('wizAlias').closest('.field'),communityField=el('wizCommunity').closest('.field'),temporary=document.createElement('div');aliasField.style.display='none';communityField.querySelector('label').textContent='Community SNMP (senha de consulta)';temporary.className='full';temporary.innerHTML=`<h3>Acesso temporário para esta execução</h3><p class="muted">Usado somente para executar o Wizard. Em usuários com domínio Huawei use <b>&gt;</b>, por exemplo: bruno&gt;default_admin.</p><div class="form-grid"><div class="field"><label>IP Huawei</label><input id="wizHost" required placeholder="10.255.255.200"></div><div class="field"><label>Porta SSH</label><input id="wizPort" type="number" min="1" max="65535" value="22" required></div><div class="field"><label>Usuário administrador temporário</label><input id="wizUser" required placeholder="bruno&gt;default_admin"></div><div class="field"><label>Senha temporária</label><input id="wizPassword" type="password" required autocomplete="new-password"></div></div><h3>Usuário permanente exclusivo do addon</h3><p class="muted">Gerado aleatoriamente. O modo manual inclui os comandos para criá-lo; o modo automático cria e salva essas credenciais.</p><div class="form-grid"><div class="field"><label>Novo usuário SSH</label><input id="addonUser" readonly></div><div class="field"><label>Nova senha SSH</label><input id="addonPassword" readonly></div></div><button type="button" id="regenerateAddon" class="secondary">GERAR OUTRAS CREDENCIAIS</button>`;grid.prepend(temporary);
 async function wizardTemporary(action,confirmWord=''){let fd=new FormData();fd.append('csrf',csrf);fd.append('action',action);fd.append('alias',el('wizAlias').value);fd.append('community',el('wizCommunity').value);fd.append('confirm',confirmWord);fd.append('wizard_host',el('wizHost').value);fd.append('wizard_port',el('wizPort').value);fd.append('wizard_user',el('wizUser').value);fd.append('wizard_password',el('wizPassword').value);el('wizReport').textContent='Executando análise temporária...';try{let r=await fetch('api_wizard.php',{method:'POST',body:fd}),j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'Falha no Wizard.');let report=`IP de origem MK-AUTH: ${j.source_ip||'-'}\nSNMP existente: ${j.snmp_configured?'sim':'não identificado'}\nACL identificada: ${j.acl_detected?'sim':'não identificado'}\nResultado: ${j.message||'-'}`;if(j.commands)report+='\n\nCOMANDOS UTILIZADOS:\n'+j.commands;if(j.test_output)report+='\n\nTESTE FINAL:\n'+j.test_output;el('wizReport').textContent=report;notice(j.message||'Wizard concluído.','ok')}catch(e){el('wizReport').textContent='ERRO: '+e.message;notice(e.message,'error')}}
 el('wizardBtn').onclick=async()=>{let j=await fetch('api_config.php?_='+Date.now()).then(r=>r.json()),c=j.config||{};el('wizHost').value=c.ssh_host||c.snmp_host||'';el('wizPort').value=c.ssh_port||22;el('wizUser').value=c.ssh_user||'';el('wizPassword').value='';openModal('wizardModal')};el('wizInventory').onclick=()=>wizardTemporary('inventory');el('wizManual').onclick=()=>wizardTemporary('generate');el('wizAuto').onclick=()=>{let word=prompt('Esta ação alterará ACL e SNMP no Huawei. Digite APLICAR para confirmar:');if(word==='APLICAR')wizardTemporary('apply',word)};
 async function refreshHealth(){let checks=await Promise.allSettled(['api_sessions.php','api_health.php','api_ssh_health.php'].map(async url=>{let r=await fetch(url+'?_='+Date.now(),{method:url==='api_sessions.php'?'GET':'POST',cache:'no-store'}),j=await r.json();return{ok:r.ok&&j.ok,error:j.error||''}}));let names=['RADIUS','SNMP','SSH'],parts=checks.map((x,i)=>x.status==='fulfilled'&&x.value.ok?`✅ ${names[i]}`:`❌ ${names[i]}: ${x.status==='fulfilled'?(x.value.error||'sem resposta'):'falha'}`),ok=checks.every(x=>x.status==='fulfilled'&&x.value.ok);healthSummary.className='feedback show '+(ok?'ok':'error');healthSummary.textContent=parts.join('  •  ')}
 radiusFrame.addEventListener('load',()=>{try{let d=radiusFrame.contentDocument,m=d&&d.querySelector('main.radius-app');if(m&&m.parentElement!==d.body){d.body.appendChild(m);cleanRadiusFrame()}}catch(e){notice('Não foi possível compactar o Radius LOG.','error')}});filter.value='';render();
})();
</script>
<script>
(function(){
 function newAddonCredentials(){let a=new Uint8Array(8);crypto.getRandomValues(a);let suffix=Array.from(a,b=>(b%36).toString(36)).join('');el('addonUser').value='mkauth-addon-'+suffix.slice(0,6);el('addonPassword').value='MkA@'+suffix+'Aa26#'}
