 el('regenerateAddon').onclick=newAddonCredentials;el('wizardBtn').onclick=async()=>{let j=await fetch('api_config.php?_='+Date.now()).then(r=>r.json()),c=j.config||{};el('wizHost').value=c.ssh_host||c.snmp_host||'';el('wizPort').value=c.ssh_port||22;el('wizUser').value=c.ssh_user||'';el('wizPassword').value='';newAddonCredentials();openModal('wizardModal')};el('wizInventory').onclick=()=>runWizardV3('inventory');el('wizManual').onclick=()=>runWizardV3('generate');el('wizAuto').onclick=async()=>{let preview=await runWizardV3('generate');if(!preview)return;setTimeout(async()=>{let word=prompt('Os comandos acima serão aplicados no Huawei e criarão o usuário dedicado exibido. Digite APLICAR para confirmar:');if(word==='APLICAR')await runWizardV3('apply',word);else notice('Aplicação automática cancelada. Nenhum comando foi enviado.','info')},250)};
})();
