<script>
(function(){
 const tableHead=document.querySelector('thead tr');tableHead.innerHTML='<th>Cliente / Login</th><th>IP</th><th>MAC</th><th>Porta / descrição</th><th>VLAN</th><th>Conectado às</th><th>Uptime</th><th>Último update</th><th>Ações</th>';
 const portFilter=document.createElement('select');portFilter.id='portFilter';portFilter.className='search';portFilter.style.marginLeft='0';portFilter.innerHTML='<option value="">Todas as portas/VLANs</option>';filter.before(portFilter);
 const parseDate=s=>{if(!s)return null;let d=new Date(String(s).replace(' ','T'));return isNaN(d)?null:d},duration=s=>{let d=parseDate(s);if(!d)return'-';let n=Math.max(0,Math.floor((Date.now()-d.getTime())/1000)),days=Math.floor(n/86400);n%=86400;let h=Math.floor(n/3600),m=Math.floor(n%3600/60);return(days?days+'d ':'')+String(h).padStart(2,'0')+'h '+String(m).padStart(2,'0')+'m'},vlanOf=p=>{let m=String(p||'').match(/(?:vlan|\.|-)(\d+)(?:\D*$)/i);return m?m[1]:'-'},dateTime=s=>{let d=parseDate(s);return d?d.toLocaleString('pt-BR'):(s||'-')};
 function updatePortFilter(){let current=portFilter.value,values=[...new Set(sessions.map(x=>x.nasportid).filter(Boolean))].sort();portFilter.innerHTML='<option value="">Todas as portas/VLANs</option>'+values.map(v=>`<option value="${esc(v)}">${esc(v)}${vlanOf(v)!=='-'?' · VLAN '+vlanOf(v):''}</option>`).join('');portFilter.value=values.includes(current)?current:''}
 render=function(){updatePortFilter();let q=filter.value.trim().toLowerCase(),port=portFilter.value,list=sessions.filter(x=>(!port||x.nasportid===port)&&[x.username,x.nome,x.framedipaddress,x.callingstationid,x.nasportid,vlanOf(x.nasportid)].join(' ').toLowerCase().includes(q));rows.innerHTML=list.map(x=>`<tr><td><a class="login" href="detail.php?login=${encodeURIComponent(x.username)}">${esc(x.nome||x.username)}<br><small>${esc(x.username)}</small></a></td><td>${esc(x.framedipaddress)}</td><td>${esc(x.callingstationid)}</td><td>${esc(x.nasportid||'-')}</td><td>${esc(vlanOf(x.nasportid))}</td><td>${esc(dateTime(x.acctstarttime))}</td><td class="uptime" data-start="${esc(x.acctstarttime)}">${duration(x.acctstarttime)}</td><td>${esc(dateTime(x.acctupdatetime))}</td><td><div class="row-actions"><a class="btn" href="detail.php?login=${encodeURIComponent(x.username)}">TRÁFEGO</a><button class="danger" onclick="disconnectClient('${esc(x.username)}')">DESCONECTAR</button></div></td></tr>`).join('');if(!list.length)rows.innerHTML='<tr><td colspan="9" class="muted">Nenhuma sessão encontrada neste filtro.</td></tr>'};portFilter.onchange=render;
 const action=document.createElement('div');action.id='actionModal';action.className='modal';action.innerHTML='<div class="modal-card" style="max-width:620px"><div class="modal-head"><strong id="actionTitle">Confirmação</strong><button class="close" id="actionClose">FECHAR</button></div><div class="modal-body"><div id="actionMessage" class="test-card"></div><div class="actions"><button id="actionConfirm" class="danger">CONFIRMAR</button><button id="actionCancel" class="secondary">CANCELAR</button></div></div></div>';document.body.appendChild(action);let pending=null;const closeAction=()=>{action.classList.remove('open');pending=null;document.body.style.overflow=''};el('actionClose').onclick=closeAction;el('actionCancel').onclick=closeAction;el('actionConfirm').onclick=()=>{let fn=pending;if(fn)fn()};
 function actionState(title,message,type='info',confirmFn=null){el('actionTitle').textContent=title;let box=el('actionMessage');box.className='test-card '+(type==='ok'?'ok':type==='error'?'error':'running');box.textContent=message;pending=confirmFn;el('actionConfirm').style.display=confirmFn?'inline-flex':'none';el('actionCancel').style.display=type==='info'&&!confirmFn?'none':'inline-flex';el('actionCancel').textContent=confirmFn?'CANCELAR':'FECHAR';action.classList.add('open');document.body.style.overflow='hidden'}
 disconnectClient=login=>actionState('Confirmar desconexão',`Desconectar ${login} do Huawei agora? O cliente perderá a conexão PPPoE.`,'info',async()=>{pending=null;el('actionConfirm').style.display='none';el('actionCancel').style.display='none';actionState('Desconectando cliente',`Enviando comando ao Huawei para ${login}...`,'info');let fd=new FormData();fd.append('csrf',csrf);fd.append('login',login);try{let r=await fetch('api_disconnect.php',{method:'POST',body:fd}),j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'Comando recusado.');actionState('Desconexão concluída',j.message,'ok');setTimeout(()=>load(true),1200)}catch(e){actionState('Falha na desconexão',e.message,'error')}});
 async function basicHealth(){let urls=['api_sessions.php','api_health.php','api_coa_health.php'],checks=await Promise.allSettled(urls.map(async(url,i)=>{let r=await fetch(url+'?_='+Date.now(),{method:i===0?'GET':'POST',cache:'no-store'}),j=await r.json();return{ok:r.ok&&j.ok,error:j.error||''}})),ok=i=>checks[i].status==='fulfilled'&&checks[i].value.ok;healthSummary.className='feedback show '+(ok(0)&&ok(1)&&ok(2)?'ok':'error');healthSummary.textContent=`${ok(0)?'✅':'❌'} RADIUS · ${ok(1)?'✅':'❌'} SNMP · ${ok(2)?'✅':'❌'} CoA 3799 · SSH opcional`}
 setInterval(()=>load(false),60000);setInterval(()=>document.querySelectorAll('.uptime').forEach(x=>x.textContent=duration(x.dataset.start)),1000);basicHealth();setTimeout(()=>render(),600);
