<script>
(function(){
 const analyze=document.createElement('button');analyze.id='patchAnalyzeBtn';analyze.textContent='PATCH PLANO E MAC';
 el('radiusBtn').after(analyze);
 const modal=document.createElement('div');modal.id='patchModal';modal.className='modal';modal.innerHTML=`<div class="modal-card"><div class="modal-head"><strong>Patch Huawei — Planos e MAC</strong><button class="close" id="patchClose">FECHAR</button></div><div class="modal-body"><p class="muted">A análise é somente leitura. A aplicação cria backup, instala a correção de MAC, sincroniza os atributos Huawei dos planos e ativa a execução automática a cada minuto.</p><div class="test-grid"><div id="patchMac" class="test-card"><b>Correção de MAC</b><p>Aguardando análise.</p></div><div id="patchPlans" class="test-card"><b>Planos Huawei</b><p>Aguardando análise.</p></div><div id="patchAuto" class="test-card"><b>Execução automática</b><p>Aguardando análise.</p></div></div><pre id="patchReport" class="code" style="margin-top:14px">Nenhuma alteração foi executada.</pre><div class="actions"><button id="patchRunAnalyze">ANALISAR NOVAMENTE</button><button id="patchRunApply" class="danger">APLICAR, CORRIGIR E ATIVAR</button></div></div></div>`;document.body.appendChild(modal);
 const cls=(node,ok)=>node.className='test-card '+(ok?'ok':'error');
 let patchData=null;
 function patchDetails(kind){if(!patchData)return;let j=patchData,text='';if(kind==='mac'){text='CORREÇÃO DE MAC\n\nTriggers encontrados:\n- '+(j.mac.triggers.length?j.mac.triggers.join('\n- '):'nenhum')+`\n\nINSERT: ${j.mac.insert===1?'OK':'PENDENTE'}\nUPDATE: ${j.mac.update===1?'OK':'PENDENTE'}\nConflitos: ${j.mac.conflicts}`;}else if(kind==='plans'){text=`PLANOS HUAWEI\n\nPlanos cadastrados: ${j.plans.total}\nHuawei-Input-Average-Rate: ${j.plans.input}/${j.plans.total}\nHuawei-Output-Average-Rate: ${j.plans.output}/${j.plans.total}\nPendentes: ${j.plans.mismatches}`;if(j.plans.pending.length){text+='\n\nDETALHES PENDENTES:';j.plans.pending.forEach(p=>{text+=`\n- ${p.nome}: esperado ${Number(p.velup||0)*1000}/${Number(p.veldown||0)*1000} bps; atual ${p.input_atual}/${p.output_atual}`})}else text+='\n\nTodos os planos estão sincronizados.';}else{text=`EXECUÇÃO AUTOMÁTICA\n\nCron instalada: ${j.automatic.configured?'SIM':'NÃO'}\nÚltima execução confirmada: ${j.automatic.last_run}\nExecução recente (até 3 min): ${j.automatic.recent?'SIM':'NÃO'}\n\nCRON:\n${j.automatic.cron||'não encontrada'}\n\nÚLTIMAS LINHAS DO LOG:\n${j.automatic.log_tail||'Sem erros registrados. Execuções bem-sucedidas são confirmadas pelo horário acima.'}`;}el('patchReport').textContent=text;}
 ['patchMac','patchPlans','patchAuto'].forEach((id,i)=>{let card=el(id);card.style.cursor='pointer';card.title='Clique para ver os detalhes';card.addEventListener('click',()=>patchDetails(['mac','plans','automatic'][i]));});
 function renderPatch(j){patchData=j;let mac=el('patchMac'),plans=el('patchPlans'),auto=el('patchAuto');cls(mac,j.mac.ok);cls(plans,j.plans.ok);cls(auto,j.automatic.ok);mac.querySelector('p').textContent=j.mac.ok?'Triggers de INSERT e UPDATE corretos; nenhum trigger conflitante.':`Triggers: insert ${j.mac.insert}, update ${j.mac.update}, conflitos ${j.mac.conflicts}.`;plans.querySelector('p').textContent=j.plans.ok?`${j.plans.total} planos sincronizados nos dois atributos Huawei.`:`${j.plans.mismatches} planos pendentes; input ${j.plans.input}/${j.plans.total}, output ${j.plans.output}/${j.plans.total}.`;auto.querySelector('p').textContent=j.automatic.ok?`Cron ativa e confirmada. Última execução: ${j.automatic.last_run}.`:j.automatic.configured?`Cron instalada, mas sem execução confirmada nos últimos 3 minutos. Última: ${j.automatic.last_run}.`:'Agendamento automático ainda não ativado.';let job=j.job?`\nÚltima solicitação #${j.job.id}: ${j.job.status} — ${j.job.message||''}`:'';el('patchReport').textContent=j.message+'\n\nClique em cada card para ver os detalhes.\n\nMAC: '+(j.mac.ok?'OK':'PENDENTE')+'\nPlanos: '+(j.plans.ok?'OK':'PENDENTE')+'\nAutomático: '+(j.automatic.ok?'ATIVO E CONFIRMADO':j.automatic.configured?'CONFIGURADO, SEM HEARTBEAT RECENTE':'INATIVO')+job;}
 async function patchStatus(){openModal('patchModal');el('patchReport').textContent='Analisando banco, triggers, atributos e agendamento...';try{let r=await fetch('api_patch.php?_='+Date.now(),{cache:'no-store'}),j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'Falha na análise.');renderPatch(j)}catch(e){el('patchReport').textContent='ERRO: '+e.message;notice(e.message,'error')}}
 async function patchApply(){el('patchRunApply').disabled=true;el('patchReport').textContent='Registrando autorização na fila segura...';let fd=new FormData();fd.append('csrf',csrf);fd.append('action','apply');try{let r=await fetch('api_patch.php',{method:'POST',body:fd}),j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'Falha na solicitação.');renderPatch(j);notice(j.message,'ok');let checks=0,poll=setInterval(async()=>{checks++;let x=await fetch('api_patch.php?_='+Date.now(),{cache:'no-store'}).then(r=>r.json());if(x.ok)renderPatch(x);if(!x.job||!['pending','running'].includes(x.job.status)||checks>=18){clearInterval(poll);el('patchRunApply').disabled=false}},5000)}catch(e){el('patchReport').textContent='ERRO: '+e.message;notice(e.message,'error');el('patchRunApply').disabled=false}}
 analyze.onclick=patchStatus;el('patchRunAnalyze').onclick=patchStatus;el('patchRunApply').onclick=patchApply;el('patchClose').onclick=()=>closeModal('patchModal');
})();
</script>
