 const community=form.elements.snmp_community.closest('.field');community.classList.add('snmp-community');
 const v3=document.createElement('div');v3.className='full snmp-v3';v3.innerHTML='<div class="form-grid"><div class="field"><label>Usuário SNMPv3</label><input name="snmp_v3_user"></div><div class="field"><label>Nível de segurança</label><select name="snmp_v3_level"><option value="authPriv">authPriv</option><option value="authNoPriv">authNoPriv</option><option value="noAuthNoPriv">noAuthNoPriv</option></select></div><div class="field v3-auth"><label>Autenticação</label><select name="snmp_v3_auth_protocol"><option>SHA</option><option>MD5</option></select></div><div class="field v3-auth"><label>Senha de autenticação</label><input name="snmp_v3_auth_password" type="password" placeholder="Deixe vazio para manter"></div><div class="field v3-priv"><label>Privacidade</label><select name="snmp_v3_priv_protocol"><option>AES</option><option>DES</option></select></div><div class="field v3-priv"><label>Senha de privacidade</label><input name="snmp_v3_priv_password" type="password" placeholder="Deixe vazio para manter"></div></div>';community.after(v3);
 const toggle=()=>{let is3=form.elements.snmp_version.value==='3',level=form.elements.snmp_v3_level.value;community.hidden=is3;v3.hidden=!is3;v3.querySelectorAll('.v3-auth').forEach(x=>x.hidden=!is3||level==='noAuthNoPriv');v3.querySelectorAll('.v3-priv').forEach(x=>x.hidden=!is3||level!=='authPriv')};form.elements.snmp_version.onchange=toggle;form.elements.snmp_v3_level.onchange=toggle;
 form.elements.ssh_host.required=false;form.elements.ssh_user.required=false;form.elements.ssh_password.required=false;
 const loadSnmp=async()=>{let j=await fetch('api_config.php?_='+Date.now(),{cache:'no-store'}).then(r=>r.json()),c=j.config||{};form.elements.snmp_version.value=c.snmp_version||'2c';form.elements.snmp_v3_user.value=c.snmp_v3_user||'';form.elements.snmp_v3_level.value=c.snmp_v3_level||'authPriv';form.elements.snmp_v3_auth_protocol.value=c.snmp_v3_auth_protocol||'SHA';form.elements.snmp_v3_priv_protocol.value=c.snmp_v3_priv_protocol||'AES';form.elements.snmp_v3_auth_password.placeholder=c.has_snmp_v3_auth_password?'Configurada — deixe vazio para manter':'Obrigatória conforme nível';form.elements.snmp_v3_priv_password.placeholder=c.has_snmp_v3_priv_password?'Configurada — deixe vazio para manter':'Obrigatória para authPriv';toggle()};loadSnmp();const previousLoad=loadConfig;loadConfig=async(first=false)=>{await previousLoad(first);await loadSnmp()};
 const head=document.querySelector('thead tr');head.innerHTML='<th>Cliente / Login</th><th>Plano</th><th>IP</th><th>MAC</th><th>Porta / descrição</th><th>VLAN</th><th>Conectado às</th><th>Uptime</th><th>Último update</th><th>Ações</th>';
 const parse=s=>{let d=s?new Date(String(s).replace(' ','T')):null;return d&&!isNaN(d)?d:null},dur=s=>{let d=parse(s);if(!d)return'-';let n=Math.max(0,Math.floor((Date.now()-d)/1000)),days=Math.floor(n/86400);n%=86400;return(days?days+'d ':'')+String(Math.floor(n/3600)).padStart(2,'0')+'h '+String(Math.floor(n%3600/60)).padStart(2,'0')+'m'},dt=s=>{let d=parse(s);return d?d.toLocaleString('pt-BR'):(s||'-')},vlan=p=>{let m=String(p||'').match(/(?:vlan|\.|-)(\d+)(?:\D*$)/i);return m?m[1]:'-'};
 render=function(){let pf=el('portFilter'),current=pf?pf.value:'',counts={};sessions.forEach(x=>{if(x.nasportid)counts[x.nasportid]=(counts[x.nasportid]||0)+1});let ports=Object.keys(counts).sort();if(pf){pf.innerHTML=`<option value="">Todas as portas/VLANs (${sessions.length} clientes)</option>`+ports.map(v=>`<option value="${esc(v)}">${esc(v)} (${counts[v]} ${counts[v]===1?'cliente':'clientes'})</option>`).join('');pf.value=ports.includes(current)?current:''}let q=filter.value.trim().toLowerCase(),list=sessions.filter(x=>(!pf||!pf.value||x.nasportid===pf.value)&&[x.username,x.nome,x.plano,x.framedipaddress,x.callingstationid,x.nasportid].join(' ').toLowerCase().includes(q));count.textContent=list.length;rows.innerHTML=list.map(x=>`<tr><td><a class="login" href="detail.php?login=${encodeURIComponent(x.username)}">${esc(x.nome||x.username)}<br><small>${esc(x.username)}</small></a></td><td><b>${esc(x.plano||'-')}</b></td><td>${esc(x.framedipaddress)}</td><td>${esc(x.callingstationid)}</td><td>${esc(x.nasportid||'-')}</td><td>${esc(vlan(x.nasportid))}</td><td>${esc(dt(x.acctstarttime))}</td><td class="uptime" data-start="${esc(x.acctstarttime)}">${dur(x.acctstarttime)}</td><td>${esc(dt(x.acctupdatetime))}</td><td><div class="row-actions"><a class="btn" href="detail.php?login=${encodeURIComponent(x.username)}">TRÁFEGO</a><button class="danger" onclick="disconnectClient('${esc(x.username)}')">DESCONECTAR</button></div></td></tr>`).join('');if(!list.length)rows.innerHTML='<tr><td colspan="10" class="muted">Nenhuma sessão encontrada neste filtro.</td></tr>'};filter.oninput=render;el('portFilter').onchange=render;setTimeout(render,300);
