<script>
(function(){
 const button=document.createElement('button');button.id='snmpSetupBtn';button.textContent='CONFIGURAR SNMP';el('userBtn').after(button);
 const modal=document.createElement('div');modal.id='snmpSetupModal';modal.className='modal';modal.innerHTML=`<div class="modal-card"><div class="modal-head"><strong>Configurar SNMP no Huawei</strong><button class="close" id="snmpSetupClose">FECHAR</button></div><div class="modal-body"><p class="muted">Gera os comandos Huawei e uma ACL exclusiva para permitir consultas somente a partir do MK-AUTH.</p><div class="form-grid"><div class="field"><label>Versão</label><select id="snmpSetupVersion"><option value="2c">SNMP v2c (recomendado)</option><option value="1">SNMP v1</option><option value="3">SNMP v3</option></select></div><div class="field"><label>ACL Huawei</label><input id="snmpSetupAcl" type="number" min="2000" max="3999" value="2998"></div><div class="field"><label>IP de origem do MK-AUTH</label><input id="snmpSetupSource" placeholder="Detectado automaticamente"></div><div class="field snmp-v12"><label>Community dedicada</label><input id="snmpSetupCommunity" type="password" placeholder="Mínimo 8 caracteres"></div><div class="field snmp-v3-create" hidden><label>Usuário SNMPv3</label><input id="snmpSetupV3User" value="mkauth_addon"></div><div class="field snmp-v3-create" hidden><label>Senha de autenticação SHA</label><input id="snmpSetupV3Auth" type="password"></div><div class="field snmp-v3-create" hidden><label>Senha de privacidade AES</label><input id="snmpSetupV3Priv" type="password"></div></div><div class="actions"><button id="snmpGenerate">GERAR COMANDOS</button><button id="snmpCopy" class="secondary">COPIAR COMANDOS</button></div><pre id="snmpCommands" class="code">Preencha os dados e clique em GERAR COMANDOS.</pre><p class="warning">A geração não altera o Huawei. Para aplicação automática com prévia e confirmação, use o WIZARD e uma credencial administrativa válida.</p></div></div>`;document.body.appendChild(modal);
 const version=el('snmpSetupVersion'),toggleCreate=()=>{let v3=version.value==='3';document.querySelectorAll('.snmp-v3-create').forEach(x=>x.hidden=!v3);document.querySelectorAll('.snmp-v12').forEach(x=>x.hidden=v3)};version.onchange=toggleCreate;
 button.onclick=()=>openModal('snmpSetupModal');el('snmpSetupClose').onclick=()=>closeModal('snmpSetupModal');
 el('snmpGenerate').onclick=async()=>{let fd=new FormData();fd.append('csrf',csrf);fd.append('version',version.value);fd.append('acl',el('snmpSetupAcl').value);fd.append('source_ip',el('snmpSetupSource').value);fd.append('community',el('snmpSetupCommunity').value);fd.append('v3_user',el('snmpSetupV3User').value);fd.append('v3_auth',el('snmpSetupV3Auth').value);fd.append('v3_priv',el('snmpSetupV3Priv').value);el('snmpCommands').textContent='Identificando a rota e gerando comandos...';try{let r=await fetch('api_snmp_template.php',{method:'POST',body:fd}),j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'Falha ao gerar comandos.');el('snmpSetupSource').value=j.source_ip;el('snmpCommands').textContent=j.commands;notice(j.message,'ok')}catch(e){el('snmpCommands').textContent='ERRO: '+e.message;notice(e.message,'error')}};
 el('snmpCopy').onclick=async()=>{let text=el('snmpCommands').textContent;if(!text||text.startsWith('ERRO:')||text.startsWith('Preencha'))return notice('Gere os comandos primeiro.','error');await navigator.clipboard.writeText(text);notice('Comandos SNMP copiados.','ok')};
})();
</script></body></html>
